<?php require_once __DIR__.'/../bootstrap.php';require_admin();$pdo->query('SELECT 1');$stats=[];foreach(['anime'=>'Anime','episodes'=>'Episodes','users'=>'Users','video_sources'=>'Sources'] as $t=>$label){$stats[$label]=(int)$pdo->query("SELECT COUNT(*) FROM `$t`")->fetchColumn();}$langs=(int)$pdo->query('SELECT COUNT(DISTINCT language) FROM video_sources WHERE active=1')->fetchColumn();$logs=$pdo->query('SELECT * FROM sync_logs ORDER BY id DESC LIMIT 8')->fetchAll();$title='Admin dashboard — AniRead';include __DIR__.'/../includes/header.php';?><h1>Admin dashboard</h1><div class="grid"><?php foreach($stats as $k=>$v):?><div class="card" style="padding:22px"><h2><?=$v?></h2><p class="muted"><?=e($k)?></p></div><?php endforeach;?><div class="card" style="padding:22px"><h2><?=$langs?></h2><p class="muted">Languages in active sources</p></div></div><section class="section"><div class="actions"><a class="btn" href="sync.php">Sync Anime</a><a class="btn alt" href="anime.php">Manage Anime</a><a class="btn alt" href="episodes.php">Episodes</a><a class="btn alt" href="sources.php">Video Sources</a><a class="btn alt" href="users.php">Users</a><a class="btn alt" href="languages.php">Languages</a><a class="btn alt" href="logout.php">Logout</a></div></section><section class="section"><h2>Recent sync activity</h2><table class="table"><tr><th>Status</th><th>Message</th><th>Started</th><th>Finished</th></tr><?php foreach($logs as $l):?><tr><td><?=e($l['status'])?></td><td><?=e($l['message'])?></td><td><?=e($l['started_at'])?></td><td><?=e($l['finished_at'])?></td></tr><?php endforeach;?></table></section><?php include __DIR__.'/../includes/footer.php';
